/**
 * Operações HTTP do recurso pedidos.
 */
import { apiRequest } from "../../../../support/api/client.js";

export function listarPedidos() {
  return apiRequest({ method: "GET", url: "/pedidos" });
}

export function criarPedido(corpo) {
  return apiRequest({ method: "POST", url: "/pedidos", body: corpo });
}

/**
 * Verificações que se repetem entre os specs de pedidos.
 */
export function validarPedidoCriado(criacao, enviado) {
  expect(criacao.status, "pedido com dados válidos deve ser criado").to.eq(201);
  expect(criacao.body.situacao, "o pedido deve nascer na situação enviada").to.eq(
    enviado.situacao,
  );
}

export function validarCriacaoRecusada(resposta, motivo) {
  expect(resposta.status, `criação de pedido deve ser recusada: ${motivo}`).to.eq(422);
}

/**
 * Listagem de pedidos: o que a coleção devolve.
 */
import { listarPedidos } from "./_support/api.js";

describe("Listar pedidos", () => {
  context("quando existem pedidos cadastrados", () => {
    // @endpoint GET /pedidos  @cat CAT-01
    it("devolve a coleção de pedidos", () => {
      listarPedidos().then((consulta) => {
        expect(consulta.status, "a listagem deve responder com sucesso").to.eq(200);
        expect(consulta.body.itens, "a coleção deve trazer os pedidos").to.have.length(2);
      });
    });

    // @endpoint GET /pedidos  @cat CAT-10
    it("devolve a primeira página no tamanho pedido", () => {
      listarPedidos({ qs: { page: 0, size: 1 } }).then((consulta) => {
        expect(consulta.body.itens, "a página deve respeitar o tamanho").to.have.length(1);
      });
    });
  });

  context("quando o pedido buscado não existe no tenant", () => {
    // @endpoint GET /pedidos  @cat CAT-06
    it("devolve a coleção vazia", () => {
      listarPedidos({ qs: { situacao: "INEXISTENTE" } }).then((consulta) => {
        expect(consulta.body.itens, "nada deve ser devolvido").to.have.length(0);
      });
    });
  });

  context("quando quem chama não está autenticado", () => {
    // @endpoint GET /pedidos  @cat CAT-08
    it("recusa a listagem de quem não fez login", () => {
      listarPedidos({ token: null }).then((resposta) => {
        expect(resposta.status, "sem identidade não se lista").to.eq(401);
      });
    });
  });
});

/**
 * Criação de pedidos: o que a API aceita e o que ela recusa.
 */
import { criarPedido } from "./_support/api.js";
import { validarPedidoCriado, validarCriacaoRecusada } from "./_support/asserts.js";

describe("Criar pedido", () => {
  context("quando os dados estão corretos", () => {
    // @endpoint POST /pedidos  @cat CAT-01
    it("cria o pedido e devolve o registro criado", () => {
      const enviado = { situacao: "ABERTO" };

      criarPedido(enviado).then((criacao) => {
        validarPedidoCriado(criacao, enviado);
      });
    });

    // @endpoint POST /pedidos  @cat CAT-11
    it("mantém um único pedido ao repetir a mesma chave", () => {
      criarPedido({ situacao: "ABERTO", chave: "k-1" }).then((primeira) => {
        criarPedido({ situacao: "ABERTO", chave: "k-1" }).then((segunda) => {
          expect(segunda.body.id, "a repetição não deve criar outro pedido").to.eq(
            primeira.body.id,
          );
        });
      });
    });
  });

  context("quando os dados estão errados", () => {
    [
      { campo: "situacao", valor: null, esperado: "nula" },
      { campo: "situacao", valor: 42, esperado: "de tipo errado" },
    ].forEach(({ campo, valor, esperado }) => {
      // @endpoint POST /pedidos  @cat CAT-02  @campo ${campo}
      // @endpoint POST /pedidos  @cat CAT-03  @campo ${campo}
      it(`recusa a criação com ${campo} ${esperado}`, () => {
        criarPedido({ [campo]: valor }).then((resposta) => {
          validarCriacaoRecusada(resposta, `${campo} ${esperado} não é aceito`);
        });
      });
    });

    // @endpoint POST /pedidos  @cat CAT-05
    it("recusa o corpo malformado", () => {
      criarPedido("isto não é um objeto").then((resposta) => {
        validarCriacaoRecusada(resposta, "o corpo precisa ser um objeto");
      });
    });
  });

  context("quando quem está chamando não tem permissão", () => {
    // @endpoint POST /pedidos  @cat CAT-08
    it("recusa a criação de quem não fez login", () => {
      criarPedido({ situacao: "ABERTO" }, { token: null }).then((resposta) => {
        expect(resposta.status, "sem identidade não se cria").to.eq(401);
      });
    });

    // @endpoint POST /pedidos  @cat CAT-09
    it("ignora a tentativa de definir o identificador", () => {
      criarPedido({ situacao: "ABERTO", id: "forjado" }).then((criacao) => {
        expect(criacao.body.id, "o identificador não pode vir do cliente").to.not.eq("forjado");
      });
    });
  });
});
